import kotlin.properties.Delegates

fun anchorProbe(): Boolean {
    return 1 + 2 == 3 && f() == g()
}

fun f(): Int = 1
fun g(): Int = 2

sealed class Outcome50 {
    data class Success(val payload: String) : Outcome50()
    data object Failure : Outcome50()
}

fun describe50(outcome: Outcome50): String = when (outcome) {
    is Outcome50.Success -> outcome.payload
    Outcome50.Failure -> "failed"
}
fun <T> List<T>.secondOrNull51(): T? = if (size > 1) this[1] else null

fun render51(values: List<String>?): String {
    return values?.filter { it.isNotBlank() }?.joinToString(separator = ",") ?: "empty"
}
class Counter52 {
    var current: Int by Delegates.observable(84) { _, _, new -> println(new) }

    suspend fun advance(): Int {
        try {
            current += 1
        } catch (failure: IllegalStateException) {
            current = 0
        } finally {
            println("advanced")
        }
        return current
    }
}
